// Go⇔TS conformance on the filter grammar, the sort parameter and the list
// request. The corpus at parse/testdata/filter_conformance.json is
// generated by the authoritative Go parser, with the schema documents the
// registry serves for its resources; the client validates each input against
// those documents and must reach the server's verdict and E-code on every
// case it can judge (tsApplicable). Regenerate the corpus with:
//
//   go test -tags=unit -run TestEmitFilterConformance -update .   (in parse/)
//
// The TS client has no parser, so it does not reconstruct the canonical AST or
// SQL (those are Go-side checks in filter_conformance_test.go). What the client
// owns — and what this test guards — is the validate-before-send contract.

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { createClient } from "../client.js";
import { SchemaValidationError } from "../core/errors.js";
import type { ResourceSchema } from "../schema.js";
import { SchemaValidator } from "../validate.js";
import type { FilterSchema, ListOptions } from "./types.js";
import { validateFilter } from "./validate.js";

interface Verdict {
  name: string;
  valid: boolean;
  errorCode?: string;
  tsApplicable?: boolean;
}

interface Corpus {
  schemas: Record<string, ResourceSchema>;
  cases: (Verdict & { input: Record<string, unknown> })[];
  sort: (Verdict & { input: string })[];
  list: (Verdict & { resource?: string; input: Record<string, string[]> })[];
}

const corpus = JSON.parse(
  readFileSync(new URL("../../../../testdata/filter_conformance.json", import.meta.url), "utf8"),
) as Corpus;

const entities = "conf_entities";

function schemaOf(resource: string): ResourceSchema {
  const schema = corpus.schemas[resource];
  if (!schema) throw new Error(`the corpus serves no schema for ${resource}`);
  return schema;
}

const related = (name: string): FilterSchema | undefined => corpus.schemas[name]?.filter;

// expectVerdict runs judge and holds its outcome to the server's verdict.
async function expectVerdict(c: Verdict, judge: () => unknown): Promise<void> {
  let thrown: unknown;
  try {
    await judge();
  } catch (e) {
    thrown = e;
  }
  if (c.valid) {
    expect(thrown, `${c.name} should validate but threw ${String(thrown)}`).toBeUndefined();
    return;
  }
  expect(thrown, `${c.name} should be rejected`).toBeInstanceOf(SchemaValidationError);
  expect((thrown as SchemaValidationError).code, c.name).toBe(c.errorCode);
}

describe("filter conformance corpus", () => {
  it("holds cases of every section", () => {
    expect(corpus.cases.length).toBeGreaterThan(0);
    expect(corpus.sort.length).toBeGreaterThan(0);
    expect(corpus.list.length).toBeGreaterThan(0);
  });

  const filterSchema = schemaOf(entities).filter;
  for (const c of corpus.cases) {
    if (c.tsApplicable === false) continue;
    it(`filter ${c.name}`, async () => {
      expect(filterSchema).toBeDefined();
      if (!filterSchema) return;
      await expectVerdict(c, () => { validateFilter(c.input, filterSchema, related); });
    });
  }

  for (const c of corpus.sort) {
    if (c.tsApplicable === false) continue;
    it(`sort ${c.name}`, async () => {
      const v = new SchemaValidator(schemaOf(entities));
      await expectVerdict(c, () => { v.validateSort(c.input); });
    });
  }

  // A list request is judged as a validating client judges what it sends:
  // the client fetches the resource's schema and its relation targets'
  // from the server, then validates every member.
  for (const c of corpus.list) {
    if (c.tsApplicable === false) continue;
    it(`list ${c.name}`, async () => {
      const resource = c.resource ?? entities;
      const fetchFn: typeof globalThis.fetch = (input) => {
        const path = new URL(input instanceof Request ? input.url : String(input)).pathname;
        const schema = /^\/([^/]+)\/schema$/.exec(path);
        const body = schema ? schemaOf(decodeURIComponent(schema[1] ?? "")) : { items: [], page_info: { has_next_page: false, has_prev_page: false } };
        return Promise.resolve(new Response(JSON.stringify(body), { headers: { "Content-Type": "application/json" } }));
      };
      const items = createClient({ baseURL: "https://api.test", fetch: fetchFn, validateBeforeSend: true }).resource<Record<string, unknown>>(resource);
      await expectVerdict(c, () => items.list(listOptions(c.input)));
    });
  }
});

// listOptions is the list a client sends as the query string q.
function listOptions(q: Record<string, string[]>): ListOptions<Record<string, unknown>> {
  const one = (name: string): string | undefined => q[name]?.[0];
  const names = (name: string): string[] | undefined => one(name)?.split(",");
  const opts: ListOptions<Record<string, unknown>> = {};
  const filter = one("filter");
  if (filter !== undefined) opts.filter = JSON.parse(filter) as Record<string, unknown>;
  const sort = one("sort");
  if (sort !== undefined) opts.sort = sort;
  const cursor = one("cursor");
  if (cursor !== undefined) opts.cursor = cursor;
  const pageSize = one("page_size");
  if (pageSize !== undefined) opts.pageSize = Number(pageSize);
  if (one("include_total") === "true") opts.includeTotal = true;
  if (one("include_deleted") === "true") opts.includeDeleted = true;
  const search = one("search");
  if (search !== undefined) opts.search = search;
  const facets = names("facets");
  if (facets) opts.facets = facets;
  const include = names("include");
  if (include) opts.include = include;
  const fields = names("fields");
  if (fields) opts.fields = fields;
  for (const name of Object.keys(q)) {
    if (!["filter", "sort", "cursor", "page_size", "include_total", "include_deleted", "search", "facets", "include", "fields"].includes(name)) {
      throw new Error(`the client sends no ${name} parameter`);
    }
  }
  return opts;
}
